// SEEDED DEFECT: cites a DIAGNOSTIC-ONLY gauge as a numeric gating threshold.
export function gate(retro) {
  if (retro.quality_score >= 90) { return 'ship'; }
  return 'block';
}

// SEEDED DEFECT: unbounded multi-row claude_sessions select — the PostgREST 1000-row
// cap silently drops the NEWEST live workers, so liveness undercounts.
export async function all(supabase) {
  return supabase.from('claude_sessions').select('session_id, heartbeat_at');
}

// SEEDED DEFECT: teardown called synchronously inside the subscribe callback.
export function wire(supabase) {
  const ch = supabase.channel('x');
  ch.on('postgres_changes', {}, () => {}).subscribe((status) => {
    if (status === 'SUBSCRIBED') {
      supabase.removeChannel(ch);
    }
  });
  return ch;
}

// SEEDED DEFECT: raw session_coordination insert bypassing insertCoordinationRow().
export async function send(supabase, payload) {
  const { error } = await supabase.from('session_coordination').insert({
    message_type: 'INFO',
    payload
  });
  return error;
}

// SEEDED DEFECT: hardcodes a DIFFERENT literal than the migration default above,
// silently negating it at insert time (the F12 drift class).
export async function create(supabase) {
  return supabase.from('seeded_widgets').insert({ status: 'draft' });
}

// SEEDED DEFECT: gates on a raw failure-COUNT delta rather than an identity-set diff.
// Uses the rule's actual lexicon (failedCount / baselineFailed) — my first seed said
// failCount, which the lexicon does not match, so the control correctly reported 0.
export function gate(baselineFailed, failedCount) {
  if (failedCount > baselineFailed) {
    throw new Error('failure count rose');
  }
  return true;
}

// SEEDED DEFECT: the raw Windows-broken direct-execution guard. argv[1] is a
// backslash path on Windows and import.meta.url is a file:// URL, so this never
// matches and the guard silently no-ops.
function main() { console.log('ran'); }
if (import.meta.url === `file://${process.argv[1]}`) main();

// SEEDED DEFECT: writes metadata.is_seeded_orphan and nothing ever reads it (ORPHAN).
export async function mark(supabase, id) {
  return supabase.from('widgets').update({ metadata: { is_seeded_orphan: true } }).eq('id', id);
}

import { vi } from 'vitest';
// SEEDED DEFECT: mocks the module under test itself.
vi.mock('../../lib/seeded-sut.js');
import { thing } from '../../lib/seeded-sut.js';
it('x', () => { expect(thing).toBeDefined(); });

// SEEDED DEFECT: venture_artifacts insert omitting the NOT-NULL title column,
// which inserts ZERO rows and swallows the error.
export async function write(supabase, ventureId) {
  return supabase.from('venture_artifacts').insert({
    venture_id: ventureId,
    lifecycle_stage: 'stage_21',
    artifact_type: 'design'
  });
}

// SEEDED DEFECT: a raw ventures insert that no producer-side assert ever checked.
export async function make(supabase) {
  return supabase.from('ventures').insert({ name: 'seeded-unguarded-row', is_demo: true });
}

// NOT the defect. A correctly guarded producer, present so the coverage denominator is
// non-zero — see the note on this spec. The lint reads source as TEXT and never imports it,
// so the unresolvable path below is irrelevant to the trial.
import { insertGuarded, CLASSIFICATION } from '../../lib/governance/fixture-producer-guard.mjs';
export async function ok(supabase) {
  return insertGuarded(supabase, 'ventures', { name: 'TEST-seeded-guarded', is_demo: true },
    { classification: CLASSIFICATION.FIXTURE, source: 'seed-trial' });
}

// SEEDED DEFECT: a hardcoded database connection string literal with an embedded credential.
// Deliberately uses the bare 'postgres' scheme, no 'ql' suffix: the control's own URL_SHAPE_RE
// accepts either spelling via an optional group (proving the same code path either way), but
// .husky/pre-commit's scanner only matches when the 'ql' suffix is present -- omitting it here
// avoids a second, unrelated pre-commit block on a fixture that is not a real credential.
export const DATABASE_URL = 'postgres://admin:hunter2seed@db.example.com:5432/prod';

-- SEEDED DEFECT: REVOKE omits PUBLIC, so anon/authenticated inherit PUBLIC's EXECUTE grant
-- and the REVOKE below is a no-op for any function that also carries a PUBLIC grant.
CREATE FUNCTION public.seeded_secdef_defect() RETURNS void LANGUAGE sql SECURITY DEFINER AS $$ SELECT 1 $$;
REVOKE EXECUTE ON FUNCTION public.seeded_secdef_defect() FROM anon, authenticated;

// SEEDED DEFECT: writes the dead-twin `progress` column instead of `progress_percentage`
// on the same UPDATE that sets status to 'completed' -- the exact class of bug
// complete-children.mjs originally shipped.
export async function markComplete(supabase, sdId) {
  return supabase.from('strategic_directives_v2').update({ status: 'completed', progress: 100 }).eq('id', sdId);
}

// SEEDED DEFECT: unconditional top-level main() call with no recognized guard -- the exact
// shape that caused the 2026-08-21 incident (a bare import of scripts/one-off/backfill-
// solomon-ledger-decision-by.mjs executed main() for real against live prod, mutating 1212
// rows irreversibly).
function main() { console.log('ran'); }
main();

// SEEDED DEFECT: a literal, machine-specific absolute home-directory path where
// resolveRepoPath('ehg') (lib/repo-paths.js) should be used instead -- the exact class of
// defect that made lib/gates/cross-repo-build-check.js and .../ui-interactivity-check.js
// silently break for any checkout not at that one path.
export const p = 'C:/Users/rickf/Projects/_EHG/ehg';

// SEEDED DEFECT: a raw supabase.rpc('release_sd', ...) call site with no expectedSdKey scope
// guard and no allowlist entry -- the exact QF-20260726-593 shape this lint exists to block.
export async function doIt(supabase, sessionId) {
  return supabase.rpc('release_sd', { p_session_id: sessionId, p_reason: 'manual' });
}

// SEEDED DEFECT: a literal Gemini model-version string outside model-config.js and not in
// scripts/lint/gemini-pin-allowlist.json -- the exact routing-pin shape this lint exists to block.
export function pickModel() {
  return 'gemini-2.5-flash';
}

// SEEDED DEFECT: a hand-rolled min_tier_rank comparison outside the single shared predicate
// (tierRankVerdict in lib/fleet/tier-ladder.cjs) -- the exact bypass shape this lint exists to
// block, since it silently reintroduces always-binding behavior regardless of ruling 1B's
// provenance-advisory branch and the TIER_FLOOR_PROVENANCE_ADVISORY reversal switch.
function claimable(sd, workerRank) {
  return sd.metadata.min_tier_rank > workerRank ? 'blocked' : 'ok';
}

const WORKTREE_PATH_RE = /[/\\]\.worktrees[/\\]([^/\\]+)/;
const key = filePath.match(WORKTREE_PATH_RE)[1];
if (key !== claimedSdKey) block();

// SEEDED DEFECT: client-side read-then-full-blob-replace metadata write.
export async function stampSeeded(supabase, id, x) {
  const { data: row } = await supabase.from('strategic_directives_v2').select('metadata').eq('id', id).maybeSingle();
  await supabase.from('strategic_directives_v2').update({ metadata: { ...row.metadata, seeded_metadata_fullblob_defect: x } }).eq('id', id);
}

// SEEDED DEFECT: derives the session-identity marker path itself instead of importing
// MARKER_DIR/markerDirs from the SSOT (lib/fleet/cc-pid-liveness.cjs) -- this SD's own root
// cause, repeated.
import path from 'node:path';
export function markerDir() { return path.join(process.cwd(), '.claude', 'session-identity'); }

// SEEDED DEFECT: a claude_sessions UPDATE setting status='released' with no is_alive write
// and no chokepoint routing -- the exact liveness-SSOT defect class SD-LEO-ORCH-CAPA-RECORD-
// TRUTH-001-E closed.
async function bad(supabase, id) {
  await supabase
    .from('claude_sessions')
    .update({ status: 'released', released_at: new Date().toISOString() })
    .eq('session_id', id);
}
